=mutation Login($email: String!, $password: String!) {
    login(input: {
      email: $email
      password: $password
    }) {
      accessToken,
      refreshToken
    }
  }

query ListParkingEvents($filter: ParkingEventFilter!, $sorting: [ParkingEventSort!], $paging: Paging!) {
  parkingEvents(filter: $filter, sorting: $sorting, paging: $paging) {
    nodes {
      id
      locationId
      vehicleId
      licencePlateNumber
      licencePlateNumberInitial
      licencePlateNumberAi
      kind
      kindInitial
      time
      cameraId
      cameraConfidenceScore
      vehicleMake
      vehicleModel
      vehicleCategory
      vehicleColor
      createdAt
      reviewStatus
      reviewStatusInitial
      session {
        id
        status
      }
      location {
        name
      }
      vehicle {
        id
        licencePlateNumber
      }
    }
    pageInfo {
      hasPreviousPage
      hasNextPage
      startCursor
      endCursor
    }
    totalCount
  }
}

