const W = $json.size?.width;
const H = $json.size?.height;
if (!W || !H) throw new Error("Missing size.width/size.height");

const b = $json.output?.bbox;
if (!b) throw new Error("Missing output.bbox");

let { x, y, w, h } = b;
const bboxConfidence = Number($json.output?.bboxConfidence || 0);

// normalize if agent ever returns percent
if (x > 1 || y > 1 || w > 1 || h > 1) {
  x /= 100;
  y /= 100;
  w /= 100;
  h /= 100;
}

// Bigger, asymmetric padding
// More width, a bit more bottom margin, because plate is often near lower front/rear area
let padX = 0.18;
let padTop = 0.12;
let padBottom = 0.26;

// If detector is less confident, expand more
if (bboxConfidence < 0.85) {
  padX += 0.06;
  padTop += 0.04;
  padBottom += 0.08;
}

// Expand bbox
let x1 = Math.max(0, x - w * padX);
let y1 = Math.max(0, y - h * padTop);
let x2 = Math.min(1, x + w + w * padX);
let y2 = Math.min(1, y + h + h * padBottom);

// Convert to pixels
let cropX = Math.max(0, Math.floor(x1 * W));
let cropY = Math.max(0, Math.floor(y1 * H));
let cropW = Math.max(1, Math.ceil((x2 - x1) * W));
let cropH = Math.max(1, Math.ceil((y2 - y1) * H));

// Enforce minimum crop size so tiny detections do not cut off the plate
const minCropW = Math.max(1, Math.round(W * 0.18));
const minCropH = Math.max(1, Math.round(H * 0.12));

if (cropW < minCropW) {
  const centerX = cropX + cropW / 2;
  cropW = minCropW;
  cropX = Math.max(0, Math.round(centerX - cropW / 2));
}

if (cropH < minCropH) {
  const centerY = cropY + cropH / 2;
  cropH = minCropH;
  cropY = Math.max(0, Math.round(centerY - cropH / 2));
}

// Clamp to image bounds
if (cropX + cropW > W) cropX = Math.max(0, W - cropW);
if (cropY + cropH > H) cropY = Math.max(0, H - cropH);
if (cropX + cropW > W) cropW = W - cropX;
if (cropY + cropH > H) cropH = H - cropY;

return {
  json: {
    ...$json,
    crop: {
      x: cropX,
      y: cropY,
      w: cropW,
      h: cropH
    }
  },
  binary: $binary
};

for (const item of items) {
  const b = item.binary?.image;  // must match Binary Property name
  if (!b) throw new Error('No binary.image found');
  b.mimeType = 'image/jpeg';
  b.fileExtension = 'jpg';
}
return items;

// Build S3 image URL from the current event id
const base = 'https://flomo-test.s3.eu-north-1.amazonaws.com';

return items.map(item => ({
  json: {
    ...item.json,
    pictureUrl: `${base}/${item.json.id}.jpg`
  },
  binary: item.binary
}));

// Keeps ONLY what crop computation needs: size + parsed bbox (from the current item).
// No binary output.

function extractOutputText(resp) {
  for (const entry of (resp.output || [])) {
    if (entry.type === "message") {
      for (const p of (entry.content || [])) {
        if (p.type === "output_text" && typeof p.text === "string") return p.text;
      }
    }
  }
  return null;
}

return items.map((item) => {
  const resp = item.json;

  // 1) read bbox text from THIS response
  const text = extractOutputText(resp);
  if (!text) {
    throw new Error("No output_text found in OpenAI response. Check resp.output[*].content[*].type.");
  }

  const parsed = JSON.parse(text); // { vehicleVisible, bboxConfidence, bbox:{x,y,w,h} }

  // 2) read size from THIS item (must be present via Merge or stored earlier)
  const W = resp.size?.width;
  const H = resp.size?.height;

  if (!W || !H) {
    throw new Error("Missing resp.size.width/height on this item. Merge Get Information output into the OpenAI response item.");
  }

  // 3) return proper n8n item
  return {
    json: {
      size: { width: W, height: H },
      output: parsed
    }
  };
});

function extractOutputText(resp) {
  for (const entry of (resp.output || [])) {
    if (entry.type === "message") {
      for (const part of (entry.content || [])) {
        if (part.type === "output_text" && typeof part.text === "string") {
          return part.text;
        }
      }
    }
  }
  return null;
}

const sourceItems = $('Init Test Metrics').all();

return $input.all().map((item, idx) => {
  const text = extractOutputText(item.json);
  if (!text) throw new Error("No output_text found in HTTP response");

  const parsed = JSON.parse(text);

  return {
    json: {
      eventId: sourceItems[idx]?.json.eventId ?? sourceItems[idx]?.json.id ?? null,
      ...parsed
    }
  };
});

function normalizePlate(p) {
  const raw = String(p || '').trim().toUpperCase();

  if (!raw) return '';

  const compact = raw
    .replace(/[\s\-\/\\]/g, '')
    .replace(/[^A-Z0-9%]/g, '');

  if (['NA', 'N/A', 'N.A', 'N.A.'].includes(raw) || compact === 'NA') {
    return 'N.A.';
  }

  return compact;
}

const allItems = $input.all();
const output = [];

for (const item of allItems) {
  const candidates = Array.isArray(item.json.candidates) ? item.json.candidates : [];

  // Debug passthrough so you can see why it failed
  if (candidates.length === 0) {
    output.push({
      json: {
        eventId: item.json.eventId ?? item.json.id ?? null,
        debug: true,
        error: 'No candidates array found for Normalize',
        inputKeys: Object.keys(item.json),
        inputPreview: item.json
      }
    });
    continue;
  }

  const seen = new Set();

  for (let idx = 0; idx < candidates.length; idx++) {
    const c = candidates[idx];
    const conf = Number(c.overallConf || 0);

    if (conf < 0.5) {
      output.push({
        json: {
          eventId: item.json.eventId ?? item.json.id ?? null,
          rank: idx + 1,
          plateRaw: c.plate || '',
          plateNormalized: 'N.A.',
          overallConf: conf,
          charConf: Array.isArray(c.charConf) ? c.charConf : [],
          notes: c.notes || '',
          hasWildcard: false,
          belowConfidenceThreshold: true
        }
      });
      continue;
    }

    const plateNormalized = normalizePlate(c.plate);

    if (!plateNormalized) continue;
    if (seen.has(plateNormalized)) continue;
    seen.add(plateNormalized);

    output.push({
      json: {
        eventId: item.json.eventId ?? item.json.id ?? null,
        rank: idx + 1,
        plateRaw: c.plate || '',
        plateNormalized,
        overallConf: conf,
        charConf: Array.isArray(c.charConf) ? c.charConf : [],
        notes: c.notes || '',
        hasWildcard: plateNormalized.includes('%'),
        belowConfidenceThreshold: false
      }
    });
  }
}

return output;

const candidate = $('Loop Over Items1').item.json;
// or $('Normalize').item.json if that is the correct candidate source

if (candidate.isLowConfidence) {
  return [{
    json: {
      ...candidate,
      dbExactExists: false,
      dbCount: 0,
      dbMatchedPlate: null,
      bestDbPlate: null,
      bestDbPlateCount: 0,
      dbMatchedPlatesCount: 0,
      wildcardMatches: [],
      dbLookupSkipped: true,
      dbSkipReason: 'overallConf_below_0_5'
    }
  }];
}

const dbRow = $json;

const rawCount =
  dbRow.eventCount ??
  dbRow.count ??
  0;

const dbCount = Number(rawCount || 0);

return [{
  json: {
    ...candidate,
    dbExactExists: dbCount > 0,
    dbCount,
    dbMatchedPlate: dbCount > 0 ? candidate.plateNormalized : null,
    bestDbPlate: null,
    bestDbPlateCount: 0,
    dbMatchedPlatesCount: dbCount > 0 ? 1 : 0,
    wildcardMatches: [],
    dbLookupSkipped: false,
    dbSkipReason: null
  }
}];

function wildcardToRegex(pattern) {
  const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('^' + escaped.replace(/%/g, '.*') + '$');
}

// take the CURRENT candidate item that entered this wildcard branch
const candidate = $('Loop Over Items1').item.json;
// if your linked node should be Normalize instead, use:
// const candidate = $('Normalize').item.json;

if (candidate.isLowConfidence) {
  return [{
    json: {
      ...candidate,
      dbExactExists: false,
      dbCount: 0,
      dbMatchedPlate: null,
      bestDbPlate: null,
      bestDbPlateCount: 0,
      dbMatchedPlatesCount: 0,
      wildcardMatches: [],
      dbLookupSkipped: true,
      dbSkipReason: 'overallConf_below_0_5'
    }
  }];
}

const candidatePlate = String(candidate.plateNormalized || '').toUpperCase();

if (!candidate.hasWildcard || !candidatePlate.includes('%')) {
  throw new Error(`Wildcard path received non-wildcard candidate: ${candidatePlate}`);
}

const regex = wildcardToRegex(candidatePlate);

// items here = all DB rows from "get all"
const matches = items
  .map(i => i.json)
  .filter(row => regex.test(String(row.plate || '').toUpperCase()));

const normalizedMatches = matches.map(row => ({
  plate: String(row.plate || '').toUpperCase(),
  count: Number(row.eventCount || row.count || 0)
}));

const dbCount = normalizedMatches.reduce((sum, row) => sum + row.count, 0);

normalizedMatches.sort((a, b) => b.count - a.count);
const best = normalizedMatches[0] || null;

return [{
  json: {
    ...candidate,
    dbExactExists: false,
    dbCount,
    dbMatchedPlate: best ? best.plate : null,
    bestDbPlate: best ? best.plate : null,
    bestDbPlateCount: best ? best.count : 0,
    dbMatchedPlatesCount: normalizedMatches.length,
    wildcardMatches: normalizedMatches,
    dbLookupSkipped: false,
    dbSkipReason: null
  }
}];

const groups = new Map();

for (const item of $input.all()) {
  const j = item.json;
  const eventId = j.eventId ?? 'unknown_event';

  const candidate = {
    rank: j.rank ?? null,
    plateRaw: j.plateRaw ?? null,
    plateNormalized: j.plateNormalized ?? null,
    overallConf: j.overallConf ?? null,
    charConf: Array.isArray(j.charConf) ? j.charConf : [],
    notes: j.notes ?? '',
    hasWildcard: !!j.hasWildcard,

    dbExactExists: !!j.dbExactExists,
    dbCount: Number(j.dbCount || 0),
    dbMatchedPlate: j.dbMatchedPlate ?? null,

    bestDbPlate: j.bestDbPlate ?? null,
    bestDbPlateCount: Number(j.bestDbPlateCount || 0),
    dbMatchedPlatesCount: Number(j.dbMatchedPlatesCount || 0),
    wildcardMatches: Array.isArray(j.wildcardMatches) ? j.wildcardMatches : []
  };

  if (!groups.has(eventId)) {
    groups.set(eventId, []);
  }

  groups.get(eventId).push(candidate);
}

const output = [];

for (const [eventId, candidates] of groups.entries()) {
  candidates.sort((a, b) => Number(a.rank || 999) - Number(b.rank || 999));

  output.push({
    json: {
      eventId,
      candidates
    }
  });
}

return output;

return items.map(item => {
  const candidates = (item.json.candidates || []).map(c => {
    const resolvedPlate = c.hasWildcard
      ? (c.bestDbPlate || null)
      : (c.plateNormalized || null);

    return {
      rank: c.rank ?? null,
      plateRaw: c.plateRaw ?? null,
      plateNormalized: c.plateNormalized ?? null,
      resolvedPlate,
      overallConf: c.overallConf ?? null,
      dbCount: Number(c.dbCount || 0),
      bestDbPlate: c.bestDbPlate ?? null,
      bestDbPlateCount: Number(c.bestDbPlateCount || 0),
      hasWildcard: !!c.hasWildcard,
      notes: c.notes ?? ''
    };
  });

  return {
    json: {
      eventId: item.json.eventId ?? null,
      candidates,
      openaiBody: {
        model: "gpt-5-mini-2025-08-07",
        input: [
          {
            role: "system",
            content:
              "You are the final parking LPN decision agent.\n" +
              "You must choose the best final licence plate from the provided candidate list, or return N.A.\n\n" +
              "Rules:\n" +
              "- You may ONLY choose finalPlate from the provided resolvedPlate values, or return null when decision='N.A.'.\n" +
              "- Never invent, rewrite, or compose a new plate.\n" +
              "- Prefer candidates with stronger image confidence and stronger DB evidence.\n" +
              "- If multiple candidates resolve to the same resolvedPlate, treat that as supporting evidence for that resolvedPlate.\n" +
              "- Wildcard candidates are only valid through their resolvedPlate.\n" +
              "- If evidence is conflicting or insufficient, return decision='N.A.'.\n" +
              "- Return JSON only."
          },
          {
            role: "user",
            content: [
              {
                type: "input_text",
                text:
                  "Choose the best final licence plate from the following enriched candidates, or return N.A.:\n\n" +
                  JSON.stringify({ candidates }, null, 2)
              }
            ]
          }
        ],
        text: {
          format: {
            type: "json_schema",
            name: "final_lpn_decision",
            strict: true,
            schema: {
              type: "object",
              additionalProperties: false,
              properties: {
                decision: {
                  type: "string",
                  enum: ["POST", "N.A."]
                },
                finalPlate: {
                  type: ["string", "null"]
                },
                chosenRank: {
                  type: ["integer", "null"]
                },
                selectedFromProvided: {
                  type: "boolean"
                },
                confidence: {
                  type: "number",
                  minimum: 0,
                  maximum: 1
                },
                reason: {
                  type: "string"
                }
              },
              required: [
                "decision",
                "finalPlate",
                "chosenRank",
                "selectedFromProvided",
                "confidence",
                "reason"
              ]
            }
          }
        }
      }
    }
  };
});

return items.map(item => ({
  json: {
    ...item.json,
    startedAtIso: new Date().toISOString(),
    startedAtMs: Date.now()
  },
  binary: item.binary
}));

function safeUsageAt(nodeName, idx) {
  try {
    const all = $(nodeName).all();
    const r = all[idx]?.json?.body ?? all[idx]?.json;

    return {
      model: r?.model ?? null,
      inputTokens: Number(r?.usage?.input_tokens || 0),
      cachedInputTokens: Number(r?.usage?.input_tokens_details?.cached_tokens || 0),
      outputTokens: Number(r?.usage?.output_tokens || 0),
      totalTokens: Number(r?.usage?.total_tokens || 0),
      used: !!r
    };
  } catch {
    return {
      model: null,
      inputTokens: 0,
      cachedInputTokens: 0,
      outputTokens: 0,
      totalTokens: 0,
      used: false
    };
  }
}

function getPricingEur(model) {
  const m = String(model || '').toLowerCase();

  if (m.includes('gpt-5-mini')) {
    return {
      inputPer1M: 0.216807,
      cachedInputPer1M: 0.021681,
      outputPer1M: 1.734455
    };
  }

  if (m.includes('gpt-5-nano')) {
    return {
      inputPer1M: 0.043361,
      cachedInputPer1M: 0.004336,
      outputPer1M: 0.346891
    };
  }

  return {
    inputPer1M: 0,
    cachedInputPer1M: 0,
    outputPer1M: 0
  };
}

function calcCostEur(u) {
  const p = getPricingEur(u.model);

  const cachedInput = Math.min(u.cachedInputTokens || 0, u.inputTokens || 0);
  const uncachedInput = Math.max(0, (u.inputTokens || 0) - cachedInput);

  const inputCostEur =
    (uncachedInput / 1_000_000) * p.inputPer1M +
    (cachedInput / 1_000_000) * p.cachedInputPer1M;

  const outputCostEur =
    ((u.outputTokens || 0) / 1_000_000) * p.outputPer1M;

  return {
    inputCostEur,
    outputCostEur,
    totalCostEur: inputCostEur + outputCostEur
  };
}

const currentItems = $input.all();
const startItems = $('Init Test Metrics').all();

return currentItems.map((item, idx) => {
  const startNode = startItems[idx]?.json ?? {};

  const startedAtIso = startNode.startedAtIso ?? null;
  const startedAtMs = Number(startNode.startedAtMs || 0);

  const finishedAtIso = new Date().toISOString();
  const finishedAtMs = Date.now();
  const latencyMs = startedAtMs ? (finishedAtMs - startedAtMs) : null;
  const latencySec = latencyMs ? Number((latencyMs / 1000).toFixed(2)) : null;

  const u1 = safeUsageAt('Find Vehicle', idx);
  const u2 = safeUsageAt('LPN Review', idx);
  const u3 = safeUsageAt('Final LPN', idx);

  const usages = [u1, u2, u3].filter(u => u.used);

  const openAiCallCount = usages.length;
  const inputTokens = usages.reduce((s, u) => s + u.inputTokens, 0);
  const cachedInputTokens = usages.reduce((s, u) => s + u.cachedInputTokens, 0);
  const outputTokens = usages.reduce((s, u) => s + u.outputTokens, 0);
  const totalTokens = usages.reduce((s, u) => s + u.totalTokens, 0);

  const modelCounts = {};
  const costByModel = {};

  let inputCostEur = 0;
  let outputCostEur = 0;
  let totalCostEur = 0;

  for (const u of usages) {
    if (u.model) {
      modelCounts[u.model] = (modelCounts[u.model] || 0) + 1;
    }

    const c = calcCostEur(u);

    inputCostEur += c.inputCostEur;
    outputCostEur += c.outputCostEur;
    totalCostEur += c.totalCostEur;

    if (u.model) {
      costByModel[u.model] ??= {
        calls: 0,
        inputTokens: 0,
        cachedInputTokens: 0,
        outputTokens: 0,
        totalTokens: 0,
        inputCostEur: 0,
        outputCostEur: 0,
        totalCostEur: 0
      };

      costByModel[u.model].calls += 1;
      costByModel[u.model].inputTokens += u.inputTokens;
      costByModel[u.model].cachedInputTokens += u.cachedInputTokens;
      costByModel[u.model].outputTokens += u.outputTokens;
      costByModel[u.model].totalTokens += u.totalTokens;
      costByModel[u.model].inputCostEur += c.inputCostEur;
      costByModel[u.model].outputCostEur += c.outputCostEur;
      costByModel[u.model].totalCostEur += c.totalCostEur;
    }
  }

  const modelsUsed = Object.keys(modelCounts).join(' | ');

  return {
    json: {
      eventId: item.json.eventId ?? null,
      startedAt: startedAtIso,
      finishedAt: finishedAtIso,
      latencyMs,
      latencySec,

      openAiCallCount,
      modelsUsed,
      modelCounts: JSON.stringify(modelCounts),

      inputTokens,
      cachedInputTokens,
      outputTokens,
      totalTokens,
      candidateCount: item.json.candidateCount ?? null,

      inputCostEur: Number(inputCostEur.toFixed(6)),
      outputCostEur: Number(outputCostEur.toFixed(6)),
      totalCostEur: Number(totalCostEur.toFixed(6)),
      costByModel: JSON.stringify(
        Object.fromEntries(
          Object.entries(costByModel).map(([model, v]) => [
            model,
            {
              ...v,
              inputCostEur: Number(v.inputCostEur.toFixed(6)),
              outputCostEur: Number(v.outputCostEur.toFixed(6)),
              totalCostEur: Number(v.totalCostEur.toFixed(6))
            }
          ])
        )
      ),

      decision: item.json.decision ?? 'N.A.',
      finalPlate: String(item.json.finalPlate || 'n.a.'),
      chosenRank: item.json.chosenRank ?? null,
      selectedFromProvided: item.json.selectedFromProvided ?? null,
      confidence: item.json.confidence ?? null,
      reason: item.json.reason ?? null
    }
  };
});

