function extractOutputText(resp) {
  for (const entry of (resp.output || [])) {
    if (entry.type === "message") {
      for (const part of (entry.content || [])) {
        if (part.type === "output_text" && typeof part.text === "string") {
          return part.text;
        }
      }
    }
  }
  return null;
}

function cleanPlate(value) {
  const raw = String(value || '').trim().toUpperCase();

  if (!raw) return null;
  if (['NA', 'N/A', 'N.A', 'N.A.'].includes(raw)) return 'n.a.';

  const compact = raw
    .replace(/[.\s\-_\/\\|]/g, '')
    .replace(/[^A-Z0-9]/g, '');

  if (!compact || compact === 'NA') return 'n.a.';

  return compact;
}

const sourceItems = $('Prepare Final Decision HTTP Body').all();
const responseItems = $input.all();

return responseItems.map((item, idx) => {
  const text = extractOutputText(item.json);
  if (!text) throw new Error(`No output_text found in Final LPN response at index ${idx}`);

  const parsed = JSON.parse(text);
  const confidence = Number(parsed.confidence || 0);
  const cleanedFinalPlate = cleanPlate(parsed.finalPlate);
  const forcedNA =
    parsed.decision !== 'POST' ||
    confidence < 0.5 ||
    !cleanedFinalPlate ||
    cleanedFinalPlate === 'n.a.';

  return {
    json: {
      eventId: sourceItems[idx]?.json.eventId ?? null,
      candidateCount: sourceItems[idx]?.json.candidateCount ?? null,
      decision: forcedNA ? 'N.A.' : 'POST',
      finalPlate: forcedNA ? 'n.a.' : cleanedFinalPlate,
      chosenRank: forcedNA ? null : (parsed.chosenRank ?? null),
      selectedFromProvided: forcedNA ? false : Boolean(parsed.selectedFromProvided),
      confidence,
      reason: forcedNA
        ? `forced_n.a.: ${parsed.reason || 'below threshold or invalid plate'}`
        : (parsed.reason || '')
    }
  };
});

const expectedByEventId = {
  "CASE_001": "EXPECTED_001",
  "CASE_002": "EXPECTED_002",
  "CASE_003": "EXPECTED_003"
};

function normalizeForCompare(value) {
  return String(value || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '');
}

return items.map(item => {
  const eventId = item.json.eventId ?? $('Loop Over Items').first().json.id;
  const expectedLpn = expectedByEventId[eventId] ?? null;
  const actualNormalized = normalizeForCompare(item.json.finalPlate);
  const expectedNormalized = normalizeForCompare(expectedLpn);

  return {
    json: {
      ...item.json,
      eventId,
      expectedLpn,
      isMatch:
        expectedLpn === null || !actualNormalized
          ? null
          : actualNormalized === expectedNormalized
    }
  };
});

const out = [];

function detectMimeFromBuffer(buf) {
  if (
    buf.length >= 3 &&
    buf[0] === 0xff &&
    buf[1] === 0xd8 &&
    buf[2] === 0xff
  ) return 'image/jpeg';

  if (
    buf.length >= 8 &&
    buf[0] === 0x89 &&
    buf[1] === 0x50 &&
    buf[2] === 0x4e &&
    buf[3] === 0x47 &&
    buf[4] === 0x0d &&
    buf[5] === 0x0a &&
    buf[6] === 0x1a &&
    buf[7] === 0x0a
  ) return 'image/png';

  if (
    buf.length >= 6 &&
    buf.toString('ascii', 0, 6) === 'GIF87a'
  ) return 'image/gif';

  if (
    buf.length >= 6 &&
    buf.toString('ascii', 0, 6) === 'GIF89a'
  ) return 'image/gif';

  if (
    buf.length >= 12 &&
    buf.toString('ascii', 0, 4) === 'RIFF' &&
    buf.toString('ascii', 8, 12) === 'WEBP'
  ) return 'image/webp';

  return null;
}

for (let i = 0; i < items.length; i++) {
