return out;

return items.map(item => ({
  json: {
    eventId: item.json.id ?? item.json.eventId ?? null,
    startedAtIso: item.json.startedAtIso ?? null,
    startedAtMs: item.json.startedAtMs ?? null
  }
}));

function cleanPlate(p) {
  return String(p || '')
    .toUpperCase()
    .replace(/[\s\-\/\\]/g, '')
    .replace(/[^A-Z0-9%]/g, '');
}

function clamp01(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(1, n));
}

function geometricMean(values) {
  if (!values.length) return 0;
  const safe = values.map(v => Math.max(0.001, clamp01(v)));
  const sumLogs = safe.reduce((a, v) => a + Math.log(v), 0);
  return Math.exp(sumLogs / safe.length);
}

return items.map(item => {
  const plateVisible = Boolean(item.json.plateVisible);
  const inputCandidates = Array.isArray(item.json.candidates) ? item.json.candidates : [];

  const processed = [];
  const seen = new Set();

  for (const c of inputCandidates) {
    const rawPlate = cleanPlate(c.plate || '');
    if (!rawPlate) continue;

    const rawCharConf = Array.isArray(c.charConf) ? c.charConf : [];

    // Align charConf length to plate length
    const charConf = rawPlate.split('').map((_, i) => {
      if (i >= rawCharConf.length) return 0.5;
      return clamp01(rawCharConf[i]);
    });

    const chars = rawPlate.split('');
    let wildcardCount = 0;
    let weakCount = 0;
    let veryWeakCount = 0;

    for (let i = 0; i < chars.length; i++) {
      const conf = charConf[i];

      if (conf < 0.75) {
        chars[i] = '%';
        wildcardCount++;
      }

      if (conf < 0.80) weakCount++;
      if (conf < 0.65) veryWeakCount++;
    }

    const wildcardedPlate = chars.join('');

    // Adjust overall confidence more conservatively
    let adjusted = geometricMean(charConf);
    adjusted -= weakCount * 0.04;
    adjusted -= veryWeakCount * 0.07;
    adjusted -= wildcardCount * 0.03;

    // Cap confidence when too much uncertainty exists
    if (wildcardCount >= 2) adjusted = Math.min(adjusted, 0.62);
    if (wildcardCount >= 3) adjusted = Math.min(adjusted, 0.50);

    adjusted = Math.max(0, Math.min(1, adjusted));

    const notes = [
      c.notes || '',
      wildcardCount > 0 ? `postprocess wildcarded=${wildcardCount}` : ''
    ].filter(Boolean).join(' | ');

    if (seen.has(wildcardedPlate)) continue;
    seen.add(wildcardedPlate);

    processed.push({
      plate: wildcardedPlate,
      overallConf: Number(adjusted.toFixed(2)),
      charConf: charConf.map(v => Number(v.toFixed(2))),
      notes
    });
  }

  processed.sort((a, b) => b.overallConf - a.overallConf);

  return {
    json: {
      ...item.json,
      plateVisible,
      candidates: processed.slice(0, 5)
    }
  };
});
